int DarTroco(decimal valor)
{
    decimal[] valores =
    {
        100m, 50m, 20m, 10m, 5m, 2m, 1m,
        0.50m, 0.25m, 0.10m, 0.05m, 0.01m
    };
    int entregues = 0;
    foreach (decimal v in valores)
    {
        int qtd = (int)(valor / v);
        if (qtd == 0)
        {
            continue;
        }
        string tipo = v >= 2 ? "nota" : "moeda";
        Console.WriteLine($"  {qtd} {tipo}(s) de {v:C}");
        valor -= qtd * v;
        entregues += qtd;
    }
    return entregues;
}

string[] metas =
{
    "Viagem a Fortaleza", "Notebook novo", "Reserva de emergência"
};
decimal[] alvos = { 4500m, 6000m, 20000m };
decimal[] aportes = { 400m, 350m, 500m };
const decimal TaxaMensal = 0.008m;
DateOnly inicio = new(2027, 1, 1);

Console.WriteLine("=== Cofrinho de Metas ===");
Console.WriteLine($"Rende {TaxaMensal:P1} ao mês (juros compostos)");
decimal jurosGeral = 0;

for (int m = 0; m < metas.Length; m++)
{
    Console.WriteLine();
    Console.WriteLine($"[{metas[m]}] alvo {alvos[m]:C}, "
        + $"guardando {aportes[m]:C}/mês");
    decimal saldo = 0;
    int mes = 0;
    while (saldo < alvos[m])
    {
        mes++;
        decimal juros = Math.Round(saldo * TaxaMensal, 2);
        saldo += juros + aportes[m];
        if (mes % 6 == 0 && saldo < alvos[m])
        {
            Console.WriteLine($"  mês {mes,2}: {saldo,12:C} "
                + Barra(saldo, alvos[m]));
        }
    }
    decimal aportado = aportes[m] * mes;
    decimal ganho = saldo - aportado;
    jurosGeral += ganho;
    int semJuros = (int)Math.Ceiling(alvos[m] / aportes[m]);
    DateOnly quando = inicio.AddMonths(mes - 1);
    Console.WriteLine($"  mês {mes,2}: {saldo,12:C} "
        + Barra(saldo, alvos[m]) + " META!");
    Console.WriteLine($"  Batida em {quando:MM/yyyy}; "
        + $"juros renderam {ganho:C}");
    Console.WriteLine($"  Sem juros levaria {semJuros} meses "
        + $"({semJuros - mes} a mais)");
}

Console.WriteLine();
Console.WriteLine($"Juros ganhos em todas as metas: {jurosGeral:C}");

string Barra(decimal saldo, decimal alvo)
{
    int cheio = (int)Math.Min(10, saldo / alvo * 10);
    string barra = new string('#', cheio)
        + new string('.', 10 - cheio);
    return $"[{barra}] {Math.Min(1m, saldo / alvo):P0}";
}

