string Converter(int opcao, double valor)
{
    return opcao switch
    {
        1 => $"{valor} km = {valor * 0.621371:F2} milhas",
        2 => $"{valor} g = {valor / 28.3495:F2} onças",
        3 => $"{valor} graus C = {valor * 9 / 5 + 32:F1} graus F",
        4 => $"{valor} L = {valor / 3.78541:F2} galões",
        5 => $"{valor} m = {valor * 3.28084:F1} pés",
        _ => throw new ArgumentException($"{opcao} não existe")
    };
}

