double Media(double[] bimestres)
{
    double soma = 0;
    foreach (double nota in bimestres)
    {
        soma += nota;
    }
    return soma / bimestres.Length;
}

string Situacao(double media, double freq)
{
    if (freq < 0.75)
    {
        return "Reprovado por falta";
    }
    return media >= 7 ? "Aprovado"
        : media >= 5 ? "Recuperação" : "Reprovado";
}

string[] palavras = { "TAPIOCA", "JANGADA" };
string[] dicas = { "comida nordestina", "barco de pescador" };
string[] jogadas = { "AEIOTPAC", "AOUNESR" };
const int MaxErros = 5;
int vitorias = 0;

Console.WriteLine("=== Jogo da Forca ===");
for (int r = 0; r < palavras.Length; r++)
{
    string palavra = palavras[r];
    char[] tela = new string('_', palavra.Length).ToCharArray();
    List<char> tentadas = new();
    int erros = 0;
    Console.WriteLine();
    Console.WriteLine($"Rodada {r + 1} - dica: {dicas[r]}");
    Console.WriteLine($"  {Mostrar(tela)}");

    foreach (char letra in jogadas[r])
    {
        if (tentadas.Contains(letra))
        {
            Console.WriteLine($"  {letra}: essa letra já foi!");
            continue;
        }
        tentadas.Add(letra);
        int achadas = Revelar(palavra, tela, letra);
        if (achadas > 0)
        {
            Console.WriteLine(
                $"  {letra}: acertou {achadas}x  {Mostrar(tela)}");
        }
        else
        {
            erros++;
            Console.WriteLine(
                $"  {letra}: errou ({erros}/{MaxErros})");
        }
        if (!tela.Contains('_') || erros == MaxErros)
        {
            break;
        }
    }

    bool venceu = !tela.Contains('_');
    vitorias += venceu ? 1 : 0;
    string fim = venceu ? "Venceu!" : "Enforcado!";
    Console.WriteLine($"  {fim} A palavra era {palavra}.");
    string usadas = string.Join(", ", tentadas);
    Console.WriteLine($"  Letras usadas: {usadas}");
}

Console.WriteLine();
Console.WriteLine($"Placar: {vitorias} de {palavras.Length} rodadas");

int Revelar(string palavra, char[] tela, char letra)
{
    int achadas = 0;
    for (int i = 0; i < palavra.Length; i++)
    {
        if (palavra[i] == letra)
        {
            tela[i] = letra;
            achadas++;
        }
    }
    return achadas;
}

string Mostrar(char[] tela) => string.Join(' ', tela);

