void Reservar(string assento)
{
    int fileira = char.ToUpper(assento[0]) - 'A';
    bool numeroOk = int.TryParse(assento[1..], out int cadeira);
    if (fileira < 0 || fileira >= Fileiras || !numeroOk
        || cadeira < 1 || cadeira > Cadeiras)
    {
        throw new ArgumentException($"{assento} não existe");
    }
    if (ocupada[fileira, cadeira - 1])
    {
        throw new InvalidOperationException($"{assento} já ocupado");
    }
    ocupada[fileira, cadeira - 1] = true;
    ocupadas++;
}

void DesenharSala()
{
    Console.WriteLine("     [ T E L A ]");
    Console.WriteLine("   1 2 3 4 5 6 7 8");
    for (int f = 0; f < Fileiras; f++)
    {
        string linha = $"{(char)('A' + f)} ";
        for (int c = 0; c < Cadeiras; c++)
        {
            linha += ocupada[f, c] ? " X" : " o";
        }
        Console.WriteLine(linha);
    }
    Console.WriteLine();
}

