class Aluno(string nome, double peso, double altura)
{
    public string Nome { get; } = nome;
    public double Peso { get; } = peso;
    public double Altura { get; } = altura is > 0.5 and < 2.5
        ? altura
        : throw new ArgumentException($"altura {altura} inválida");
    public double Imc => Peso / (Altura * Altura);

    public string Faixa => Imc switch
    {
        < 18.5 => "Abaixo do peso",
        < 25 => "Peso normal",
        < 30 => "Sobrepeso",
        _ => "Obesidade"
    };

    public override string ToString() =>
        $"{Nome,-10} {Peso,6:F1} {Altura,6:F2} {Imc,5:F1}  {Faixa}";
}

