class Produto(string nome, int quantidade, int minimo, decimal custo)
{
    public string Nome { get; } = nome;
    public int Quantidade { get; private set; } = quantidade;
    public int Minimo { get; } = minimo;
    public decimal Custo { get; } = custo;
    public bool AbaixoDoMinimo => Quantidade < Minimo;

    public void Movimentar(int qtd)
    {
        if (Quantidade + qtd < 0)
        {
            throw new InvalidOperationException(
                $"saída de {-qtd} x {Nome}, só há {Quantidade}");
        }
        Quantidade += qtd;
    }
}

