string Horas(TimeSpan t, bool comSinal = false)
{
    string sinal = t < TimeSpan.Zero ? "-" : comSinal ? "+" : "";
    TimeSpan abs = t.Duration();
    return $"{sinal}{(int)abs.TotalHours:00}:{abs.Minutes:00}";
}

class DiaDePonto(DateOnly data, string texto)
{
    private readonly TimeOnly[] _batidas =
        [.. texto.Split(' ').Select(TimeOnly.Parse)];
    public DateOnly Data { get; } = data;
    public bool Completo => _batidas.Length is 2 or 4;
    public TimeOnly Entrada => _batidas[0];
    public TimeSpan Almoco => _batidas.Length == 4
        ? _batidas[2] - _batidas[1] : TimeSpan.Zero;
    public TimeSpan Trabalhado => _batidas[^1] - Entrada - Almoco;
    public string Marcacoes =>
        string.Join(" ", _batidas.Select(b => $"{b:HH:mm}"));
}

