Jogo? Ler(string sumula)
{
    string[] p = sumula.Split(' ');
    return p.Length == 5 && p[2] == "x" && p[0] != p[4]
        && int.TryParse(p[1], out int casa) && casa >= 0
        && int.TryParse(p[3], out int fora) && fora >= 0
        ? new Jogo(p[0], casa, fora, p[4])
        : null;
}

Time Buscar(string nome) => times.TryGetValue(nome, out Time? time)
    ? time
    : times[nome] = new Time(nome);

record Jogo(string Casa, int GolsCasa, int GolsFora, string Fora);

class Time(string nome)
{
    private readonly List<(int Pro, int Contra)> _jogos = [];
    public string Nome { get; } = nome;
    public int Jogos => _jogos.Count;
    public int Vitorias => _jogos.Count(j => j.Pro > j.Contra);
    public int Empates => _jogos.Count(j => j.Pro == j.Contra);
    public int GolsPro => _jogos.Sum(j => j.Pro);
    public int Saldo => GolsPro - _jogos.Sum(j => j.Contra);
    public int Pontos => Vitorias * 3 + Empates;

    public void Somar(int gp, int gc) => _jogos.Add((gp, gc));
    public override string ToString() =>
        $"{Nome,-11}{Pontos,3}{Jogos,3}{Vitorias,3}{Empates,3}"
        + $"{GolsPro,4}{Saldo,4:+0;-0;0}";
}

