record Emprestimo(string Leitor, DateOnly Retirada);

class Biblioteca(decimal multaDia, params string[] titulos)
{
    const int Prazo = 14;
    readonly Dictionary<string, Emprestimo?> _acervo =
        titulos.ToDictionary(t => t, _ => (Emprestimo?)null);
    public decimal Multas { get; private set; }
    public int Disponiveis => _acervo.Values.Count(e => e is null);

    public void Emprestar(string titulo, string leitor, DateOnly data)
    {
        if (!Achar(titulo, out var atual)) return;
        if (atual is not null)
        {
            Console.WriteLine($"{leitor}: '{titulo}' está com "
                + atual.Leitor);
            return;
        }
        _acervo[titulo] = new Emprestimo(leitor, data);
        Console.WriteLine($"{data:dd/MM} {leitor} levou '{titulo}'"
            + $" (até {data.AddDays(Prazo):dd/MM})");
    }

    public void Devolver(string titulo, DateOnly data)
    {
        if (!Achar(titulo, out var atual)) return;
        if (atual is null)
        {
            Console.WriteLine($"'{titulo}' já estava na estante");
            return;
        }
        int dias = data.DayNumber - atual.Retirada.DayNumber;
        decimal multa = Math.Max(0, dias - Prazo) * multaDia;
        Multas += multa;
        _acervo[titulo] = null;
        Console.WriteLine($"{data:dd/MM} {atual.Leitor} devolveu "
            + $"'{titulo}' após {dias} dias, multa de {multa:C}");
    }

    bool Achar(string titulo, out Emprestimo? atual)
    {
        if (_acervo.TryGetValue(titulo, out atual)) return true;
        Console.WriteLine($"'{titulo}' não faz parte do acervo");
        return false;
    }
}

