enum Risco { Vermelho, Laranja, Amarelo, Verde, Azul }

record Paciente(string Nome, Risco Risco, TimeOnly Chegada);

class ProntoSocorro
{
    readonly PriorityQueue<Paciente, (Risco, int)> _fila = new();
    readonly List<(Paciente Paciente, int Espera)> _atendidos = [];
    int _senha;

    public int NaFila => _fila.Count;

    public void Chegar(Paciente p)
    {
        _senha++;
        _fila.Enqueue(p, (p.Risco, _senha));
        Console.WriteLine($"{p.Chegada:HH:mm} senha {_senha:D2} "
            + $"{p.Nome} ({p.Risco})");
    }

    public void Atender(TimeOnly agora)
    {
        if (!_fila.TryDequeue(out var p, out _))
        {
            Console.WriteLine($"{agora:HH:mm} ninguém na fila");
            return;
        }
        int espera = (int)(agora - p.Chegada).TotalMinutes;
        _atendidos.Add((p, espera));
        Console.WriteLine($"{agora:HH:mm} >> vez de {p.Nome}"
            + $" (esperou {espera} min)");
    }

    public void Resumo()
    {
        Console.WriteLine("--- Fim do plantão ---");
        var media = _atendidos.Average(a => a.Espera);
        Console.WriteLine($"Atendidos: {_atendidos.Count}");
        Console.WriteLine($"Espera média: {media:F1} min");
        var grupos = _atendidos
            .GroupBy(a => a.Paciente.Risco)
            .OrderBy(g => g.Key);
        foreach (var g in grupos)
        {
            var maior = g.Max(a => a.Espera);
            Console.WriteLine(
                $"{g.Key,-9} {g.Count()} | espera máx {maior} min");
        }
    }
}

