record Lancamento(DateOnly Data, string Descricao, decimal Valor);

abstract class Conta(string tipo)
{
    readonly List<Lancamento> _extrato = [];
    public decimal Saldo => _extrato.Sum(l => l.Valor);
    public string Tipo => tipo;
    protected virtual decimal Disponivel => Saldo;
    public abstract void FecharMes(DateOnly data);
    public void Lancar(DateOnly data, string texto, decimal valor) =>
        _extrato.Add(new Lancamento(data, texto, valor));

    public bool Sacar(DateOnly data, string texto, decimal valor)
    {
        if (valor > Disponivel)
        {
            Console.WriteLine($"Negado: {texto} {valor:C} ({Tipo})");
            return false;
        }
        Lancar(data, texto, -valor);
        return true;
    }

    public void Transferir(Conta para, DateOnly data, decimal valor)
    {
        if (!Sacar(data, $"Envio p/ {para.Tipo}", valor)) return;
        para.Lancar(data, $"Vindo da {Tipo}", valor);
    }

    public void ImprimirExtrato()
    {
        Console.WriteLine($"--- Extrato da {Tipo} ---");
        foreach (var (dia, desc, v) in _extrato)
        {
            Console.WriteLine($"{dia:dd/MM} {desc,-20}{v,10:N2}");
        }
        Console.WriteLine($"Saldo final: {Saldo:C}");
    }
}

class ContaCorrente(decimal limite) : Conta("Corrente")
{
    protected override decimal Disponivel => Saldo + limite;
    public override void FecharMes(DateOnly data) =>
        Lancar(data, "Tarifa do pacote", -24.90m);
}

class ContaPoupanca(decimal taxa) : Conta("Poupança")
{
    public override void FecharMes(DateOnly data) =>
        Lancar(data, "Rendimento", Math.Round(Saldo * taxa, 2));
}

