abstract class Lutador(string nome, int vida)
{
    public string Nome => nome;
    public int Vida { get; private set; } = vida;
    public bool Vivo => Vida > 0;
    protected virtual double ChanceCritico => 0.10;
    protected abstract int Forca();

    public void Atacar(Lutador alvo, Random dado)
    {
        int dano = Forca() + dado.Next(0, 6);
        bool critico = dado.NextDouble() < ChanceCritico;
        dano = critico ? dano * 2 : dano;
        alvo.Vida = Math.Max(0, alvo.Vida - dano);
        var txt = critico ? $"{dano} CRÍTICO!" : $"{dano}";
        Console.WriteLine(
            $"{Nome} -> {alvo.Nome}: -{txt} (vida {alvo.Vida})");
    }
}

class Guerreiro(string nome) : Lutador(nome, 70)
{
    protected override int Forca() => 11;
}

class Maga(string nome) : Lutador(nome, 45)
{
    int _mana = 30;
    protected override int Forca()
    {
        if (_mana < 10) return 4;
        _mana -= 10;
        return 18;
    }
}

class Arqueira(string nome) : Lutador(nome, 50)
{
    protected override double ChanceCritico => 0.35;
    protected override int Forca() => 8;
}

class Monstro(string nome, int vida, int forca) : Lutador(nome, vida)
{
    protected override int Forca() => forca;
}

