enum Status { Recebido, Preparando, EmRota, Entregue, Cancelado }
delegate void AoMudar(Pedido pedido, Status anterior);
class Pedido(int numero, string cliente, string prato, decimal valor)
{
    public int Numero => numero;
    public string Cliente => cliente;
    public string Prato => prato;
    public decimal Valor => valor;
    public Status Status { get; private set; }

    public bool TentarMudar(Status novo)
    {
        bool pode = novo == Status.Cancelado
            ? Status < Status.EmRota : novo == Status + 1;
        if (pode) Status = novo;
        return pode;
    }
}

class Central(HashSet<string> esgotados)
{
    readonly Queue<Pedido> _fila = new();
    public event AoMudar? StatusMudou;

    public void Receber(Pedido pedido) => _fila.Enqueue(pedido);

    public void ProcessarFila()
    {
        while (_fila.TryDequeue(out var p))
        {
            if (esgotados.Contains(p.Prato))
            {
                Mudar(p, Status.Cancelado);
                continue;
            }
            Mudar(p, Status.Preparando);
            Mudar(p, Status.EmRota);
            Mudar(p, Status.Entregue);
        }
    }

    public void Mudar(Pedido p, Status novo)
    {
        var antes = p.Status;
        if (p.TentarMudar(novo)) StatusMudou?.Invoke(p, antes);
        else Console.WriteLine($"#{p.Numero}: não pode virar {novo}");
    }
}

