static IEnumerable<Resultado> Importar(string texto)
{
    var linhas = texto.Split('\n', StringSplitOptions.TrimEntries);
    for (int i = 1; i < linhas.Length; i++)
    {
        yield return Validar(i + 1, linhas[i].Split(';'));
    }
}
static Resultado Validar(int n, string[] c)
{
    if (c.Length != 5) return new Recusada(n, "número de colunas");
    if (c[0] is "") return new Recusada(n, "nome vazio");
    if (!c[1].Contains('@')) return new Recusada(n, "e-mail sem @");
    if (!DateOnly.TryParseExact(c[2], "dd/MM/yyyy", out var nasc))
    {
        return new Recusada(n, $"data '{c[2]}' não existe");
    }
    if (!Enum.TryParse<Plano>(c[3], out var plano)
        || !Enum.IsDefined(plano))
    {
        return new Recusada(n, $"plano '{c[3]}' desconhecido");
    }
    if (!decimal.TryParse(c[4], out var valor) || valor <= 0)
    {
        return new Recusada(n, $"mensalidade '{c[4]}' inválida");
    }
    return new Aceita(n, new Aluno(c[0], nasc, plano, valor));
}

enum Plano { Bronze, Prata, Ouro }
record Aluno(string Nome, DateOnly Nascimento, Plano Plano,
    decimal Valor);
abstract record Resultado(int Linha);
record Aceita(int Linha, Aluno Aluno) : Resultado(Linha);
record Recusada(int Linha, string Motivo) : Resultado(Linha);

