void Reservar(string nome, int num, DateOnly ent, DateOnly sai)
{
    var quarto = quartos.Buscar(num);
    var ocupado = reservas.Todos().Any(r => r.Quarto == num
        && ent < r.Saida && r.Entrada < sai);
    string? erro = quarto switch
    {
        null => $"quarto {num} não existe",
        _ when sai <= ent => "saída antes da entrada",
        _ when ocupado => "quarto já ocupado nessas datas",
        _ => null,
    };
    if (quarto is null || erro is not null)
    {
        Console.WriteLine($"X  {nome}: {erro}");
        return;
    }
    decimal total = (sai.DayNumber - ent.DayNumber) * quarto.Diaria;
    int id = reservas.Quantidade + 1;
    reservas.Salvar(new Reserva(id, nome, num, ent, sai, total));
    Console.WriteLine($"OK {nome}: {quarto.Tipo} {num}, "
        + $"{ent:dd}-{sai:dd/MM}, {total:C}");
}

