static async IAsyncEnumerable<Lance> ReceberLancesAsync(
    [EnumeratorCancellation] CancellationToken ct = default)
{
    var quem = "Ana Beto Beto Ana Caio Caio Beto".Split(' ');
    int[] centenas = [140, 152, 160, 163, 165, 175, 190];
    for (int i = 0; i < quem.Length; i++)
    {
        await Task.Delay(10, ct);
        var hora = new TimeOnly(20, i * 3);
        yield return new Lance(quem[i], centenas[i] * 100m, hora);
    }
}
record Lance(string Quem, decimal Valor, TimeOnly Hora);
record Resultado(string Item, string? Vencedor, decimal Valor,
    int Lances, int Participantes);
class Leilao(string item, decimal minimo, decimal passo)
{
    readonly List<Lance> _aceitos = [];
    public event EventHandler<Lance>? NovoLider;
    public event Action<Lance, string>? Recusado;
    Lance? Lider => _aceitos.LastOrDefault();

    public void Registrar(Lance lance)
    {
        string? motivo = Lider switch
        {
            null when lance.Valor < minimo => $"mínimo de {minimo:C}",
            { Quem: var q } when q == lance.Quem => "você já lidera",
            { Valor: var v } when lance.Valor < v + passo =>
                $"precisa de pelo menos {v + passo:C}",
            _ => null,
        };
        if (motivo is not null)
        {
            Recusado?.Invoke(lance, motivo);
            return;
        }
        _aceitos.Add(lance);
        NovoLider?.Invoke(this, lance);
    }

    public async Task<Resultado> EncerrarAsync(CancellationToken ct)
    {
        Console.WriteLine("Dou-lhe uma... dou-lhe duas...");
        await Task.Delay(30, ct);
        Console.WriteLine($"Vendido: {Lider?.Quem ?? "ninguém"}!");
        int pessoas = _aceitos.Select(l => l.Quem).Distinct().Count();
        return new Resultado(item, Lider?.Quem, Lider?.Valor ?? 0,
            _aceitos.Count, pessoas);
    }
}

