sealed class Historico
{
    private readonly Stack<Comando> _feitos = new(), _refazer = new();
    public void Executar(Comando c)
    {
        Console.WriteLine($"[Comando] {c.Nome}");
        c.Fazer();
        _feitos.Push(c);
        _refazer.Clear();
    }
    public void Desfazer() =>
        Mover(_feitos, _refazer, "Desfazer", c => c.Desfazer);
    public void Refazer() =>
        Mover(_refazer, _feitos, "Refazer", c => c.Fazer);
    public override string ToString() =>
        $"desfazer {_feitos.Count}, refazer {_refazer.Count}";
    private static void Mover(Stack<Comando> de, Stack<Comando> para,
        string rotulo, Func<Comando, Action> acao)
    {
        if (de.TryPop(out var c))
        {
            Console.WriteLine($"[{rotulo}] {c.Nome}");
            acao(c)();
            para.Push(c);
        }
    }
}

