sealed class Ocioso() : Estado("Ocioso")
{
    public override Estado? Inserir() => new AguardandoPin(0);
}

sealed class AguardandoPin(int erros) : Estado($"PIN, erros {erros}/3")
{
    public override Estado? Pin(Caixa c, string pin) =>
        c.PinConfere(pin) ? new Autenticado()
        : erros + 1 == 3 ? new Bloqueado()
        : new AguardandoPin(erros + 1);
}

sealed class Autenticado() : Estado("Autenticado")
{
    public override Estado? Sacar(Caixa c, decimal valor) =>
        c.Debitar(valor) ? this : null;
    public override Estado? Ejetar() => new Ocioso();
}

sealed class Bloqueado() : Estado("Bloqueado (cartão retido)");

sealed class Caixa(string pin, decimal saldo)
{
    private Estado _estado = new Ocioso();
    public decimal Saldo { get; private set; } = saldo;
    public void Inserir() => Aplicar("cartão", e => e.Inserir());
    public void Pin(string p) => Aplicar("PIN", e => e.Pin(this, p));
    public void Sacar(decimal v) =>
        Aplicar($"sacar {v:N0}", e => e.Sacar(this, v));
    public void Ejetar() => Aplicar("ejetar", e => e.Ejetar());
    public bool PinConfere(string p) => p == pin;
    public bool Debitar(decimal valor)
    {
        bool cabe = valor <= Saldo;
        Saldo -= cabe ? valor : 0;
        return cabe;
    }
    private void Aplicar(string acao, Func<Estado, Estado?> transicao)
    {
        var novo = transicao(_estado);
        Console.WriteLine($"{acao,-10} " + (novo is null
            ? $"NEGADO em {_estado.Nome}"
            : novo == _estado ? $"ok, saldo R$ {Saldo:N2}"
            : $"{_estado.Nome} -> {novo.Nome}"));
        _estado = novo ?? _estado;
    }
}

