sealed class Spec<T>(string descricao, Func<T, bool> regra)
{
    public string Descricao => descricao;
    public bool Satisfaz(T item) => regra(item);

    public static Spec<T> operator &(Spec<T> a, Spec<T> b) =>
        new($"({a.Descricao} E {b.Descricao})",
            x => a.Satisfaz(x) && b.Satisfaz(x));
    public static Spec<T> operator |(Spec<T> a, Spec<T> b) =>
        new($"({a.Descricao} OU {b.Descricao})",
            x => a.Satisfaz(x) || b.Satisfaz(x));
    public static Spec<T> operator !(Spec<T> a) =>
        new($"NÃO {a.Descricao}", x => !a.Satisfaz(x));
}

interface IRepositorio<T>
{
    void Adicionar(T item);
    IReadOnlyList<T> Listar(Spec<T> spec);
    int Contar(Spec<T> spec);
}

sealed class RepositorioEmMemoria<T> : IRepositorio<T>
{
    private readonly List<T> _itens = [];
    public void Adicionar(T item) => _itens.Add(item);
    public IReadOnlyList<T> Listar(Spec<T> spec) =>
        _itens.Where(spec.Satisfaz).ToList();
    public int Contar(Spec<T> spec) => _itens.Count(spec.Satisfaz);
}

