sealed record Result<T>(T? Valor, string? Erro)
{
    public static Result<T> Ok(T valor) => new(valor, null);
    public static Result<T> Falha(string erro) => new(default, erro);
    public Result<TNovo> Entao<TNovo>(Func<T, Result<TNovo>> passo)
        => Erro is null ? passo(Valor!) : Result<TNovo>.Falha(Erro);
    public override string ToString() =>
        Erro is null ? $"ok -> {Valor}" : $"ERRO: {Erro}";
}

readonly record struct Reais
{
    public decimal Valor { get; }
    private Reais(decimal valor) => Valor = valor;
    public static Result<Reais> Criar(decimal v) => v > 0
        ? Result<Reais>.Ok(new(v))
        : Result<Reais>.Falha("valor precisa ser positivo");
    public static Reais operator +(Reais a, Reais b) =>
        new(a.Valor + b.Valor);
    public static Reais operator -(Reais a, Reais b) =>
        new(a.Valor - b.Valor);
    public override string ToString() => $"R$ {Valor:N2}";
}

abstract record Evento;
sealed record Depositado(Reais Valor, Reais Saldo) : Evento;
sealed record Sacado(Reais Valor, Reais Saldo, DateOnly Dia) : Evento;

sealed class Carteira(decimal limiteDiario)
{
    private readonly List<Evento> _eventos = [];
    private (DateOnly Dia, Reais Soma) _hoje;
    public Reais Saldo { get; private set; }
    public IReadOnlyList<Evento> Eventos => _eventos;
    public Result<Reais> Depositar(Reais valor)
    {
        Saldo += valor;
        _eventos.Add(new Depositado(valor, Saldo));
        return Result<Reais>.Ok(Saldo);
    }
    public Result<Reais> Sacar(Reais valor, DateOnly dia)
    {
        var noDia = valor + (_hoje.Dia == dia ? _hoje.Soma : default);
        if (valor.Valor > Saldo.Valor || noDia.Valor > limiteDiario)
        {
            return Result<Reais>.Falha(valor.Valor > Saldo.Valor
                ? $"saldo é {Saldo}" : "passa do limite diário");
        }
        _hoje = (dia, noDia);
        Saldo -= valor;
        _eventos.Add(new Sacado(valor, Saldo, dia));
        return Result<Reais>.Ok(Saldo);
    }
}

