sealed class CacheComTtl<T>(TimeProvider relogio, TimeSpan ttl)
{
    private sealed record Entrada(T Valor, DateTimeOffset Expira);
    private readonly Dictionary<string, Entrada> _itens = [];
    public (T Valor, bool DoCache) ObterOuCriar(string chave,
        Func<string, T> buscarNaFonte)
    {
        var agora = relogio.GetUtcNow();
        if (_itens.TryGetValue(chave, out var e) && agora < e.Expira)
        {
            return (e.Valor, true);
        }
        var valor = buscarNaFonte(chave);
        _itens[chave] = new(valor, agora + ttl);
        return (valor, false);
    }
}

sealed class TokenBucket(TimeProvider relogio, int max, double taxa)
{
    private DateTimeOffset _ultimaRecarga = relogio.GetUtcNow();
    public double Fichas { get; private set; } = max;
    public bool TentarConsumir()
    {
        var agora = relogio.GetUtcNow();
        double passou = (agora - _ultimaRecarga).TotalSeconds;
        Fichas = Math.Min(max, Fichas + passou * taxa);
        _ultimaRecarga = agora;
        bool temFicha = Fichas >= 1;
        Fichas -= temFicha ? 1 : 0;
        return temFicha;
    }
}

sealed class RelogioFalso(DateTimeOffset inicio) : TimeProvider
{
    private DateTimeOffset _agora = inicio;
    public override DateTimeOffset GetUtcNow() => _agora;
    public void Avancar(TimeSpan tempo) => _agora += tempo;
}

