    {
        acumulador -= Passo;
        mundo.Atualizar(Passo, ++passos * Passo);
        if (passos % 10 == 0)
        {
            Console.WriteLine($"-- {passos / 10}s: quadro {quadros}, "
                + $"x={mundo.Heroi.X:F1}, {mundo.Pontos} pts");
        }
    }
}
Console.WriteLine($"Quadros: {quadros} | passos de física: {passos}");
Console.WriteLine($"Pontos: {mundo.Pontos} | vidas: {mundo.Vidas}");

enum Tipo { Heroi, Moeda, Pedra }

sealed class Entidade(Tipo tipo, double x, int faixa, double vx = 0)
{
    private const double Lado = 0.8;
    public Tipo Tipo => tipo;
    public double X { get; private set; } = x;
    public int Faixa { get; private set; } = faixa;
    public void Mover(double dt) => X += vx * dt;
    public void TrocarFaixa() => Faixa = 1 - Faixa;
    public bool Colide(Entidade o) => Faixa == o.Faixa
        && X < o.X + Lado && X + Lado > o.X;
}

sealed class Mundo(Random rng)
{
    private readonly List<Entidade> _itens =
        [.. Enumerable.Range(0, 16).Select(i => rng.Next(3) == 0
            ? new Entidade(Tipo.Pedra, 3 + i * 1.2, rng.Next(2), -1)
            : new Entidade(Tipo.Moeda, 3 + i * 1.2, rng.Next(2)))];
    public Entidade Heroi { get; } = new(Tipo.Heroi, 0, 0, 3);
    public int Pontos { get; private set; }
    public int Vidas { get; private set; } = 3;
    public void Atualizar(double dt, double t)
    {
        Heroi.Mover(dt);
        _itens.ForEach(i => i.Mover(dt));
        bool perigo = _itens.Any(i => i.Tipo == Tipo.Pedra
            && i.Faixa == Heroi.Faixa
            && i.X - Heroi.X is > 0 and < 1.5);
        if (perigo && rng.NextDouble() < 0.5)
        {
            Heroi.TrocarFaixa();
            Console.WriteLine($"[{t:F1}s] troca de faixa");
        }
        foreach (var item in _itens.FindAll(i => i.Colide(Heroi)))
        {
            _itens.Remove(item);
            (Pontos, Vidas) = item.Tipo == Tipo.Moeda
                ? (Pontos + 10, Vidas) : (Pontos, Vidas - 1);
            Console.WriteLine($"[{t:F1}s] pegou {item.Tipo}: "
                + $"{Pontos} pts, {Vidas} vida(s)");
        }
    }
}

using System.Collections.Concurrent;
using System.Threading.Channels;

Nota[] lote =
[
    new(1001, "Padaria Sol", 1250m), new(1002, "Oficina Zé", 830.5m),
    new(1003, "Mercado Bom", 4200m), new(1004, "Farmácia Vida", 312m),
    new(1005, "", 99.9m), new(1006, "Bar do Léo", 640m),
    new(1007, "Loja Tchê", 0m), new(1008, "Sorveteria Ki", 188m),
    new(1009, "Ótica Luz", 1575m), new(1010, "Pet Amigo", 452.3m),
];
const decimal Aliquota = 0.18m;
var fila = Channel.CreateBounded<Nota>(capacity: 3);
var resultados = new ConcurrentBag<Resultado>();
var trava = new Lock();
int emAndamento = 0, pico = 0;
using var prazo = new CancellationTokenSource(10_000);

Console.WriteLine("=== Emissor de NF-e: Channel + 3 workers ===");
var workers = Enumerable.Range(0, 3)
    .Select(_ => TrabalharAsync(prazo.Token)).ToList();
foreach (var nota in lote)
{
    await fila.Writer.WriteAsync(nota, prazo.Token);
}
fila.Writer.Complete();
await Task.WhenAll(workers);
Console.WriteLine(string.Join('\n',
    resultados.OrderBy(r => r.Numero).Select(r => r.Linha)));
Console.WriteLine($"Emitidas: {resultados.Count(r => r.Icms > 0)} de "
    + $"{lote.Length} | pico: {pico} notas em paralelo");
Console.WriteLine($"ICMS total: R$ {resultados.Sum(r => r.Icms):N2}");

async Task TrabalharAsync(CancellationToken ct)
{
    await foreach (var nota in fila.Reader.ReadAllAsync(ct))
    {
        int agora = Interlocked.Increment(ref emAndamento);
        lock (trava)
        {
            pico = Math.Max(pico, agora);
        }
        try
        {
            resultados.Add(await EmitirAsync(nota, ct));
        }
        finally
        {
            Interlocked.Decrement(ref emAndamento);
        }
    }
}

async Task<Resultado> EmitirAsync(Nota nota, CancellationToken ct)
{
    await Task.Delay(15 + nota.Numero % 3 * 10, ct);
    string cabeca = $"NF {nota.Numero} {nota.Cliente,-13}";
    string? erro = nota.Cliente == "" ? "sem destinatário"
        : nota.Valor <= 0 ? "valor zerado" : null;
    if (erro is not null)
    {
        return new(nota.Numero, $"{cabeca} REJEITADA: {erro}", 0);
    }
    decimal icms = decimal.Round(nota.Valor * Aliquota, 2);
    string valores = $"{nota.Valor,9:N2} ICMS {icms,7:N2}";
    return new(nota.Numero, cabeca + valores, icms);
}

