Retorno Salvar(Transacao t, Pedido p, string evento)
{
    t.Gravar(() => banco[p.Id] = p);
    t.Gravar(() => outbox.Add(new Mensagem(evento, p.Id)));
    return new(true, $"pedido {p.Id} + evento {evento}");
}

interface IComando;
interface IConsulta<TResposta>;
sealed record Pedir(string Sabor, decimal Preco) : IComando;
sealed record Pagar(int Id) : IComando;
sealed record Faturamento : IConsulta<decimal>;
sealed record Pedido(int Id, string Sabor, decimal Preco, bool Pago);
sealed record Retorno(bool Ok, string Mensagem);
sealed record Mensagem(string Evento, int Id);

sealed class Transacao
{
    private readonly List<Action> _gravacoes = [];
    public void Gravar(Action gravacao) => _gravacoes.Add(gravacao);
    public void Commit() => _gravacoes.ForEach(gravar => gravar());
}

sealed class Mediador
{
    private readonly Dictionary<Type, Delegate> _handlers = [];
    public void Comando<T>(Func<T, Transacao, Retorno> handler)
        where T : IComando => _handlers[typeof(T)] = handler;
    public void Consulta<T, TR>(Func<T, TR> handler)
        where T : IConsulta<TR> => _handlers[typeof(T)] = handler;
    public TR Perguntar<T, TR>(T consulta) where T : IConsulta<TR> =>
        ((Func<T, TR>)_handlers[typeof(T)])(consulta);
    public void Enviar<T>(T comando) where T : IComando
    {
        Console.WriteLine($"[Comando] {comando}");
        var transacao = new Transacao();
        var h = (Func<T, Transacao, Retorno>)_handlers[typeof(T)];
        var r = h(comando, transacao);
        if (r.Ok)
        {
            transacao.Commit();
        }
        string acao = r.Ok ? "commit" : "descartada";
        Console.WriteLine($"   [Transação] {acao}: {r.Mensagem}");
    }
}

