sealed record Pedido(string Nome, int Qtd, decimal Valor, string Cep);
sealed record Resultado(bool Ok, string Erro = "",
    bool Transitorio = false);
sealed record Passo(string Nome, Func<Pedido, Resultado> Executar,
    Action<Pedido> Compensar);

sealed class Servico(decimal inicial, string erro)
{
    public decimal Atual { get; private set; } = inicial;
    public Resultado Debitar(decimal valor)
    {
        bool cabe = valor <= Atual;
        Atual -= cabe ? valor : 0;
        return new(cabe, cabe ? "" : erro);
    }
    public void Creditar(decimal valor) => Atual += valor;
}

sealed class Saga(Action<TimeSpan> esperar, params Passo[] passos)
{
    public void Rodar(Pedido p)
    {
        Console.WriteLine($"[Saga] pedido de {p.Nome}: R$ {p.Valor}");
        var feitos = new Stack<Passo>();
        foreach (var passo in passos)
        {
            var r = passo.Executar(p);
            for (int ms = 200; r.Transitorio && ms <= 800; ms *= 2)
            {
                Console.WriteLine($"   [Retry] {r.Erro}: +{ms} ms");
                esperar(TimeSpan.FromMilliseconds(ms));
                r = passo.Executar(p);
            }
            if (!r.Ok)
            {
                Console.WriteLine($"   [!] {passo.Nome}: {r.Erro}");
                while (feitos.TryPop(out var feito))
                {
                    feito.Compensar(p);
                    Console.WriteLine($"   [Compensa] {feito.Nome}");
                }
                return;
            }
            feitos.Push(passo);
            Console.WriteLine($"   [ok] {passo.Nome}");
        }
        Console.WriteLine("   [Saga] concluída");
    }
}
